// Test the threshold parsing logic
const VALID_METRIC_IDS = ['exact_match', 'toxicity', 'length_variance'];

function parseThresholds(thresholdStrs) {
  if (!thresholdStrs || thresholdStrs.length === 0) {
    return null;
  }

  const thresholds = {};
  for (const str of thresholdStrs) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: ${str}`);
    }

    const [, metricId, minStr] = match;
    const min = parseFloat(minStr);

    if (!VALID_METRIC_IDS.includes(metricId)) {
      throw new Error(`Unknown metric: ${metricId}. Valid metrics are: ${VALID_METRIC_IDS.join(', ')}`);
    }

    if (isNaN(min) || min < 0 || min > 1) {
      throw new Error(`Invalid threshold value: ${minStr}. Must be between 0 and 1`);
    }

    thresholds[metricId] = min;
  }

  return thresholds;
}

// Test cases
console.log('Test 1: Valid thresholds');
console.log(parseThresholds(['exact_match=0.9', 'toxicity=0.95']));

console.log('\nTest 2: Null thresholds');
console.log(parseThresholds(null));

console.log('\nTest 3: Empty thresholds');
console.log(parseThresholds([]));

try {
  console.log('\nTest 4: Malformed threshold');
  parseThresholds(['exact_match0.9']);
} catch (e) {
  console.log('Error:', e.message);
}

try {
  console.log('\nTest 5: Unknown metric');
  parseThresholds(['unknown_metric=0.9']);
} catch (e) {
  console.log('Error:', e.message);
}

try {
  console.log('\nTest 6: Invalid threshold value');
  parseThresholds(['exact_match=1.5']);
} catch (e) {
  console.log('Error:', e.message);
}

console.log('\nAll tests passed!');
EOF
node /tmp/test_thresholds.mjs
